//! What plugins return, as Rust types the edge hands to the core (docs/plugin-host-spec.md, section 8).
//!
//! The contract's values arrive as types generated by `bindgen!`; they are converted here, at the boundary, so that
//! durations are [`Duration`]s and nothing generated reaches a public API. Ids are the provider's own, opaque.

use std::time::Duration;

use crate::ByteSize;
use crate::bindings::base::vehicoule::plugin::types;
use crate::bindings::search::exports::vehicoule::plugin::search;

/// A picture of an item, as the provider serves it.
#[non_exhaustive]
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Artwork {
    /// Where the picture is.
    pub url: String,
    /// Its width in pixels, when the provider says.
    pub width: Option<u32>,
    /// Its height in pixels, when the provider says.
    pub height: Option<u32>,
}

/// An artist named by another item.
#[non_exhaustive]
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ArtistRef {
    /// The provider's id of the artist.
    pub id: String,
    /// The artist's name.
    pub name: String,
}

/// An album named by a track.
#[non_exhaustive]
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct AlbumRef {
    /// The provider's id of the album.
    pub id: String,
    /// The album's title.
    pub title: String,
}

/// A track.
#[non_exhaustive]
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Track {
    /// The provider's id of the track.
    pub id: String,
    /// The track's title.
    pub title: String,
    /// Its artists, in the provider's order.
    pub artists: Vec<ArtistRef>,
    /// Its album, when it has one.
    pub album: Option<AlbumRef>,
    /// Its duration, when the provider says.
    pub duration: Option<Duration>,
    /// Its ISRC, when the provider says.
    pub isrc: Option<String>,
    /// Its artwork, in the provider's order.
    pub artwork: Vec<Artwork>,
}

/// An album.
#[non_exhaustive]
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Album {
    /// The provider's id of the album.
    pub id: String,
    /// The album's title.
    pub title: String,
    /// Its artists, in the provider's order.
    pub artists: Vec<ArtistRef>,
    /// Its release year, when the provider says.
    pub year: Option<u16>,
    /// Its artwork, in the provider's order.
    pub artwork: Vec<Artwork>,
}

/// An artist.
#[non_exhaustive]
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Artist {
    /// The provider's id of the artist.
    pub id: String,
    /// The artist's name.
    pub name: String,
    /// Their artwork, in the provider's order.
    pub artwork: Vec<Artwork>,
}

/// A playlist.
#[non_exhaustive]
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Playlist {
    /// The provider's id of the playlist.
    pub id: String,
    /// The playlist's title.
    pub title: String,
    /// Who made it, when the provider says.
    pub owner: Option<String>,
    /// Its artwork, in the provider's order.
    pub artwork: Vec<Artwork>,
}

/// One result of a search.
#[non_exhaustive]
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Item {
    /// A track.
    Track(Track),
    /// An album.
    Album(Album),
    /// An artist.
    Artist(Artist),
    /// A playlist.
    Playlist(Playlist),
}

/// A kind of item a search asks for.
#[non_exhaustive]
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum ItemKind {
    /// Tracks.
    Track,
    /// Albums.
    Album,
    /// Artists.
    Artist,
    /// Playlists.
    Playlist,
}

/// One page of search results.
#[non_exhaustive]
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Page {
    /// The results, in the provider's order.
    pub items: Vec<Item>,
    /// The cursor of the next page, opaque, when there is one.
    pub next: Option<String>,
}

/// The size of a returned value, for the output budget (section 6): the bytes of every string, plus one for every
/// element of every list, so that a long list of empty or small values counts too.
///
/// A value's fixed-size parts (numbers, enums) are bounded through its lists and by the plugin's memory ceiling, since
/// the host reads every value out of that memory.
pub(crate) trait OutputSize {
    fn output_size(&self) -> usize;
}

impl OutputSize for String {
    fn output_size(&self) -> usize {
        self.len()
    }
}

impl<T: OutputSize> OutputSize for Option<T> {
    fn output_size(&self) -> usize {
        self.as_ref().map_or(0, OutputSize::output_size)
    }
}

impl<T: OutputSize> OutputSize for Vec<T> {
    fn output_size(&self) -> usize {
        self.iter().fold(self.len(), |sum, value| {
            sum.saturating_add(value.output_size())
        })
    }
}

/// The output size of a value, as a [`ByteSize`] to compare with the output budget.
pub(crate) fn output_bytes<T: OutputSize>(value: &T) -> ByteSize {
    ByteSize::new(u64::try_from(value.output_size()).unwrap_or(u64::MAX))
}

/// The sum of the output sizes of the given parts, saturated.
fn sum(parts: &[usize]) -> usize {
    parts
        .iter()
        .fold(0, |total, part| total.saturating_add(*part))
}

impl OutputSize for Artwork {
    fn output_size(&self) -> usize {
        self.url.output_size()
    }
}

impl OutputSize for ArtistRef {
    fn output_size(&self) -> usize {
        sum(&[self.id.output_size(), self.name.output_size()])
    }
}

impl OutputSize for AlbumRef {
    fn output_size(&self) -> usize {
        sum(&[self.id.output_size(), self.title.output_size()])
    }
}

impl OutputSize for Track {
    fn output_size(&self) -> usize {
        sum(&[
            self.id.output_size(),
            self.title.output_size(),
            self.artists.output_size(),
            self.album.output_size(),
            self.isrc.output_size(),
            self.artwork.output_size(),
        ])
    }
}

impl OutputSize for Album {
    fn output_size(&self) -> usize {
        sum(&[
            self.id.output_size(),
            self.title.output_size(),
            self.artists.output_size(),
            self.artwork.output_size(),
        ])
    }
}

impl OutputSize for Artist {
    fn output_size(&self) -> usize {
        sum(&[
            self.id.output_size(),
            self.name.output_size(),
            self.artwork.output_size(),
        ])
    }
}

impl OutputSize for Playlist {
    fn output_size(&self) -> usize {
        sum(&[
            self.id.output_size(),
            self.title.output_size(),
            self.owner.output_size(),
            self.artwork.output_size(),
        ])
    }
}

impl OutputSize for Item {
    fn output_size(&self) -> usize {
        match self {
            Self::Track(track) => track.output_size(),
            Self::Album(album) => album.output_size(),
            Self::Artist(artist) => artist.output_size(),
            Self::Playlist(playlist) => playlist.output_size(),
        }
    }
}

impl OutputSize for Page {
    fn output_size(&self) -> usize {
        sum(&[self.items.output_size(), self.next.output_size()])
    }
}

impl From<types::Artwork> for Artwork {
    fn from(artwork: types::Artwork) -> Self {
        Self {
            url: artwork.url,
            width: artwork.width,
            height: artwork.height,
        }
    }
}

impl From<types::ArtistRef> for ArtistRef {
    fn from(artist: types::ArtistRef) -> Self {
        Self {
            id: artist.id,
            name: artist.name,
        }
    }
}

impl From<types::AlbumRef> for AlbumRef {
    fn from(album: types::AlbumRef) -> Self {
        Self {
            id: album.id,
            title: album.title,
        }
    }
}

impl From<types::Track> for Track {
    fn from(track: types::Track) -> Self {
        Self {
            id: track.id,
            title: track.title,
            artists: convert(track.artists),
            album: track.album.map(AlbumRef::from),
            duration: track.duration_ms.map(Duration::from_millis),
            isrc: track.isrc,
            artwork: convert(track.artwork),
        }
    }
}

impl From<types::Album> for Album {
    fn from(album: types::Album) -> Self {
        Self {
            id: album.id,
            title: album.title,
            artists: convert(album.artists),
            year: album.year,
            artwork: convert(album.artwork),
        }
    }
}

impl From<types::Artist> for Artist {
    fn from(artist: types::Artist) -> Self {
        Self {
            id: artist.id,
            name: artist.name,
            artwork: convert(artist.artwork),
        }
    }
}

impl From<types::Playlist> for Playlist {
    fn from(playlist: types::Playlist) -> Self {
        Self {
            id: playlist.id,
            title: playlist.title,
            owner: playlist.owner,
            artwork: convert(playlist.artwork),
        }
    }
}

impl From<types::Item> for Item {
    fn from(item: types::Item) -> Self {
        match item {
            types::Item::Track(track) => Self::Track(track.into()),
            types::Item::Album(album) => Self::Album(album.into()),
            types::Item::Artist(artist) => Self::Artist(artist.into()),
            types::Item::Playlist(playlist) => Self::Playlist(playlist.into()),
        }
    }
}

impl From<ItemKind> for types::ItemKind {
    fn from(kind: ItemKind) -> Self {
        match kind {
            ItemKind::Track => Self::Track,
            ItemKind::Album => Self::Album,
            ItemKind::Artist => Self::Artist,
            ItemKind::Playlist => Self::Playlist,
        }
    }
}

impl From<search::Page> for Page {
    fn from(page: search::Page) -> Self {
        Self {
            items: convert(page.items),
            next: page.next,
        }
    }
}

fn convert<A, B: From<A>>(values: Vec<A>) -> Vec<B> {
    values.into_iter().map(B::from).collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    fn artwork(url: &str) -> types::Artwork {
        types::Artwork {
            url: url.to_owned(),
            width: Some(1),
            height: Some(2),
        }
    }

    fn artist(id: &str) -> types::ArtistRef {
        types::ArtistRef {
            id: id.to_owned(),
            name: format!("name of {id}"),
        }
    }

    #[test]
    fn a_track_keeps_every_field_and_its_duration_becomes_a_duration() {
        let track = Track::from(types::Track {
            id: "t".to_owned(),
            title: "Title".to_owned(),
            artists: vec![artist("a1"), artist("a2")],
            album: Some(types::AlbumRef {
                id: "al".to_owned(),
                title: "Album".to_owned(),
            }),
            duration_ms: Some(215_000),
            isrc: Some("FRZ039800212".to_owned()),
            artwork: vec![artwork("https://x/1"), artwork("https://x/2")],
        });
        assert_eq!(track.id, "t");
        assert_eq!(track.title, "Title");
        assert_eq!(
            track
                .artists
                .iter()
                .map(|a| a.id.as_str())
                .collect::<Vec<_>>(),
            ["a1", "a2"]
        );
        assert_eq!(track.artists[1].name, "name of a2");
        assert_eq!(
            track
                .album
                .as_ref()
                .map(|a| (a.id.as_str(), a.title.as_str())),
            Some(("al", "Album"))
        );
        assert_eq!(track.duration, Some(Duration::from_secs(215)));
        assert_eq!(track.isrc.as_deref(), Some("FRZ039800212"));
        assert_eq!(
            track.artwork,
            [
                Artwork {
                    url: "https://x/1".to_owned(),
                    width: Some(1),
                    height: Some(2)
                },
                Artwork {
                    url: "https://x/2".to_owned(),
                    width: Some(1),
                    height: Some(2)
                }
            ]
        );
    }

    #[test]
    fn every_item_variant_converts_to_its_own_variant() {
        let album = types::Album {
            id: "al".to_owned(),
            title: "Album".to_owned(),
            artists: vec![artist("a")],
            year: Some(1998),
            artwork: vec![artwork("https://x")],
        };
        let Item::Album(converted) = Item::from(types::Item::Album(album)) else {
            panic!("an album must stay an album");
        };
        assert_eq!(
            (
                converted.id.as_str(),
                converted.title.as_str(),
                converted.year
            ),
            ("al", "Album", Some(1998))
        );
        assert_eq!(converted.artists.len(), 1);
        assert_eq!(converted.artwork.len(), 1);

        let Item::Artist(converted) = Item::from(types::Item::Artist(types::Artist {
            id: "ar".to_owned(),
            name: "Artist".to_owned(),
            artwork: vec![artwork("https://x")],
        })) else {
            panic!("an artist must stay an artist");
        };
        assert_eq!(
            (converted.id.as_str(), converted.name.as_str()),
            ("ar", "Artist")
        );
        assert_eq!(converted.artwork.len(), 1);

        let Item::Playlist(converted) = Item::from(types::Item::Playlist(types::Playlist {
            id: "p".to_owned(),
            title: "Playlist".to_owned(),
            owner: Some("me".to_owned()),
            artwork: vec![artwork("https://x")],
        })) else {
            panic!("a playlist must stay a playlist");
        };
        assert_eq!(
            (
                converted.id.as_str(),
                converted.title.as_str(),
                converted.owner.as_deref()
            ),
            ("p", "Playlist", Some("me"))
        );
        assert_eq!(converted.artwork.len(), 1);
    }

    #[test]
    fn every_item_kind_maps_to_its_own_kind() {
        let pairs = [
            (ItemKind::Track, types::ItemKind::Track),
            (ItemKind::Album, types::ItemKind::Album),
            (ItemKind::Artist, types::ItemKind::Artist),
            (ItemKind::Playlist, types::ItemKind::Playlist),
        ];
        for (ours, wit) in pairs {
            assert_eq!(types::ItemKind::from(ours), wit);
        }
    }

    #[test]
    fn the_output_size_counts_every_string_once() {
        // 1 + 5 (id, title) + 1 + 2 + 9 (one artist) + 2 + 5 (album) + 12 (isrc) + 1 + 10 (one artwork) = 48.
        let track = Track {
            id: "t".to_owned(),
            title: "Title".to_owned(),
            artists: vec![ArtistRef {
                id: "a1".to_owned(),
                name: "name of a".to_owned(),
            }],
            album: Some(AlbumRef {
                id: "al".to_owned(),
                title: "Album".to_owned(),
            }),
            duration: None,
            isrc: Some("FRZ039800212".to_owned()),
            artwork: vec![Artwork {
                url: "https://x/".to_owned(),
                width: None,
                height: None,
            }],
        };
        assert_eq!(track.output_size(), 48);
        let page = Page {
            items: vec![
                Item::Track(track),
                Item::Album(Album {
                    id: "al".to_owned(),
                    title: "Album".to_owned(),
                    artists: Vec::new(),
                    year: None,
                    artwork: Vec::new(),
                }),
                Item::Artist(Artist {
                    id: "ar".to_owned(),
                    name: "Artist".to_owned(),
                    artwork: Vec::new(),
                }),
                Item::Playlist(Playlist {
                    id: "p".to_owned(),
                    title: "Playlist".to_owned(),
                    owner: Some("me".to_owned()),
                    artwork: Vec::new(),
                }),
            ],
            next: Some("page-2".to_owned()),
        };
        // 4 items + 48 + (2 + 5) + (2 + 6) + (1 + 8 + 2) + 6 = 84.
        assert_eq!(page.output_size(), 84);
    }

    #[test]
    fn every_list_element_counts_even_when_empty() {
        assert_eq!(vec![String::new(); 3].output_size(), 3);
        assert_eq!(vec![vec![String::new(); 2]; 3].output_size(), 9);
        assert_eq!(Vec::<String>::new().output_size(), 0);
    }
}
